INSERT INTO `about_sections` (`id`, `center_id`, `title`, `heading`, `description`, `subtext`, `feature_list`, `image_url`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'Get To Know Us', 'Quality coaching at EduSphere Chennai Central', 'EduSphere Chennai Central is part of the EduSphere Academy network. We combine experienced faculty, structured study material and regular testing so students always know where they stand.\n\nOur programs cover CAT / MBA, Bank Exams, GATE, GMAT, ICET, JEE/Engg, NEET, CLAT, IPM, in classroom, online live and hybrid formats.', 'Committed to results, mentoring and long-term career growth.', '[\"Experienced faculty\",\"Small batch sizes\",\"Weekly tests with analysis\",\"Personal mentoring\"]', '/assets/demo/campus.jpg', 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(2, 2, 'Get To Know Us', 'Quality coaching at EduSphere Bengaluru Koramangala', 'EduSphere Bengaluru Koramangala is part of the EduSphere Academy network. We combine experienced faculty, structured study material and regular testing so students always know where they stand.\n\nOur programs cover CAT / MBA, Bank Exams, GATE, GMAT, JEE/Engg, IPM, in classroom, online live and hybrid formats.', 'Committed to results, mentoring and long-term career growth.', '[\"Experienced faculty\",\"Small batch sizes\",\"Weekly tests with analysis\",\"Personal mentoring\"]', '/assets/demo/study-group-3.jpg', 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(3, 3, 'Get To Know Us', 'Quality coaching at EduSphere Hyderabad Ameerpet', 'EduSphere Hyderabad Ameerpet is part of the EduSphere Academy network. We combine experienced faculty, structured study material and regular testing so students always know where they stand.\n\nOur programs cover CAT / MBA, Bank Exams, GATE, ICET, JEE/Engg, NEET, in classroom, online live and hybrid formats.', 'Committed to results, mentoring and long-term career growth.', '[\"Experienced faculty\",\"Small batch sizes\",\"Weekly tests with analysis\",\"Personal mentoring\"]', '/assets/demo/classroom-2.jpg', 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(4, 4, 'Get To Know Us', 'Quality coaching at EduSphere Pune Deccan', 'EduSphere Pune Deccan is part of the EduSphere Academy network. We combine experienced faculty, structured study material and regular testing so students always know where they stand.\n\nOur programs cover CAT / MBA, Bank Exams, GMAT, JEE/Engg, CLAT, IPM, in classroom, online live and hybrid formats.', 'Committed to results, mentoring and long-term career growth.', '[\"Experienced faculty\",\"Small batch sizes\",\"Weekly tests with analysis\",\"Personal mentoring\"]', '/assets/demo/library-2.jpg', 1, '2026-10-28 21:09:20', '2026-10-28 21:09:20'),
(5, 5, 'Get To Know Us', 'Quality coaching at EduSphere Delhi Laxmi Nagar', 'EduSphere Delhi Laxmi Nagar is part of the EduSphere Academy network. We combine experienced faculty, structured study material and regular testing so students always know where they stand.\n\nOur programs cover CAT / MBA, Bank Exams, GATE, NEET, CLAT, in classroom, online live and hybrid formats.', 'Committed to results, mentoring and long-term career growth.', '[\"Experienced faculty\",\"Small batch sizes\",\"Weekly tests with analysis\",\"Personal mentoring\"]', '/assets/demo/classroom-3.jpg', 1, '2026-10-28 21:09:21', '2026-10-28 21:09:21'),
(6, 6, 'Get To Know Us', 'Quality coaching at EduSphere Kolkata Salt Lake', 'EduSphere Kolkata Salt Lake is part of the EduSphere Academy network. We combine experienced faculty, structured study material and regular testing so students always know where they stand.\n\nOur programs cover CAT / MBA, Bank Exams, GATE, JEE/Engg, NEET, CLAT, in classroom, online live and hybrid formats.', 'Committed to results, mentoring and long-term career growth.', '[\"Experienced faculty\",\"Small batch sizes\",\"Weekly tests with analysis\",\"Personal mentoring\"]', '/assets/demo/students-group-2.jpg', 1, '2026-10-28 21:09:22', '2026-10-28 21:09:22');
