INSERT INTO `blog_posts` (`id`, `center_id`, `title`, `slug`, `excerpt`, `content`, `featured_image_url`, `author_name`, `published_date`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 1, 'Mock Tests Done Right: Analyse, Don\'t Just Attempt', 'mock-tests-done-right-analyse-don-t-just-attempt', 'The score is the least useful number in a mock. Here is what to look at instead.', '<p>After every mock, sort your questions into four buckets: correct and fast, correct but slow, wrong, and skipped.</p><p>The \"correct but slow\" bucket is where most marks are hiding. Re-solve those questions with a timer.</p><p>For wrong answers, write the reason in one line — concept gap, calculation slip or misread question.</p><p>Track these reasons across mocks. When one reason keeps repeating, that is your next week of preparation.</p>', '/assets/demo/analytics.jpg', 'Priya Sharma', '2026-10-25', 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(2, 1, 'CLAT: Reading Speed Is Your Biggest Lever', 'clat-reading-speed-is-your-biggest-lever', 'Every CLAT section is passage-based. Faster, accurate reading lifts every score at once.', '<p>CLAT has around 120 questions built on passages of 450 words each — over 20,000 words in two hours.</p><p>Read one editorial and one long-form article every day, timing yourself and noting the main argument in one sentence.</p><p>Practise skimming for structure first: claim, evidence, counter-argument, conclusion.</p><p>Speed without accuracy does not help, so check comprehension with five questions after every timed read.</p>', '/assets/demo/library-2.jpg', 'Zoya Mukherjee', '2026-10-16', 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(3, 1, 'Bank PO vs Clerk: Which Exam Should You Target?', 'bank-po-vs-clerk-which-exam-should-you-target', 'Pay, career growth and difficulty compared — and why many aspirants prepare for both.', '<p>The PO exam has a mains paper with descriptive English and an interview; the clerk exam ends at mains.</p><p>Starting pay for a PO is roughly 1.6 times that of a clerk, and promotions to manager scale come faster.</p><p>The syllabus overlaps by about 80%, so a combined plan is efficient: prepare for PO-level depth, and the clerk paper becomes a speed test.</p><p>Decide on your target based on how soon you need a job and how comfortable you are with interviews.</p>', '/assets/demo/finance-calc.jpg', 'Lakshmi Krishnan', '2026-10-07', 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(4, 1, 'How to Build a 6-Month CAT Study Plan', 'how-to-build-a-6-month-cat-study-plan', 'A month-by-month plan that balances concepts, sectional practice and full-length mocks.', '<p>Six months is enough time for CAT if you split it into three clear phases: concepts, application and simulation.</p><p>In the first two months, cover every Quant topic and read one long article a day for VARC. Keep DILR practice light but regular: two sets a day.</p><p>From month three, move to timed sectional tests. Log every mistake by topic and type, and revise the log every Sunday.</p><p>The last two months are for full-length mocks: two a week, each followed by an analysis session that takes longer than the mock itself.</p>', '/assets/demo/desk-planner.jpg', 'Dr. Arun Mehta', '2026-09-28', 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(5, 2, 'Bank PO vs Clerk: Which Exam Should You Target?', 'bank-po-vs-clerk-which-exam-should-you-target', 'Pay, career growth and difficulty compared — and why many aspirants prepare for both.', '<p>The PO exam has a mains paper with descriptive English and an interview; the clerk exam ends at mains.</p><p>Starting pay for a PO is roughly 1.6 times that of a clerk, and promotions to manager scale come faster.</p><p>The syllabus overlaps by about 80%, so a combined plan is efficient: prepare for PO-level depth, and the clerk paper becomes a speed test.</p><p>Decide on your target based on how soon you need a job and how comfortable you are with interviews.</p>', '/assets/demo/finance-calc.jpg', 'Lakshmi Krishnan', '2026-10-25', 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(6, 2, 'CLAT: Reading Speed Is Your Biggest Lever', 'clat-reading-speed-is-your-biggest-lever', 'Every CLAT section is passage-based. Faster, accurate reading lifts every score at once.', '<p>CLAT has around 120 questions built on passages of 450 words each — over 20,000 words in two hours.</p><p>Read one editorial and one long-form article every day, timing yourself and noting the main argument in one sentence.</p><p>Practise skimming for structure first: claim, evidence, counter-argument, conclusion.</p><p>Speed without accuracy does not help, so check comprehension with five questions after every timed read.</p>', '/assets/demo/library-2.jpg', 'Zoya Mukherjee', '2026-10-16', 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(7, 2, 'NEET Biology: The Chapters That Decide Your Rank', 'neet-biology-the-chapters-that-decide-your-rank', 'Ten NCERT chapters account for nearly half of the biology questions. Start there.', '<p>Biology is 360 of the 720 marks in NEET, and the questions stay very close to NCERT text.</p><p>Human Physiology, Genetics, Ecology, Plant Physiology and Cell Biology together contribute the largest share every year.</p><p>Read each chapter line by line, then turn diagrams into flashcards. Revisit them every ten days.</p><p>Practise assertion–reason questions separately; they reward precise reading more than memory.</p>', '/assets/demo/medical-brain.jpg', 'Dr. Ishita Pillai', '2026-10-07', 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(8, 2, 'Mock Tests Done Right: Analyse, Don\'t Just Attempt', 'mock-tests-done-right-analyse-don-t-just-attempt', 'The score is the least useful number in a mock. Here is what to look at instead.', '<p>After every mock, sort your questions into four buckets: correct and fast, correct but slow, wrong, and skipped.</p><p>The \"correct but slow\" bucket is where most marks are hiding. Re-solve those questions with a timer.</p><p>For wrong answers, write the reason in one line — concept gap, calculation slip or misread question.</p><p>Track these reasons across mocks. When one reason keeps repeating, that is your next week of preparation.</p>', '/assets/demo/analytics.jpg', 'Priya Sharma', '2026-09-28', 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(9, 3, 'Bank PO vs Clerk: Which Exam Should You Target?', 'bank-po-vs-clerk-which-exam-should-you-target', 'Pay, career growth and difficulty compared — and why many aspirants prepare for both.', '<p>The PO exam has a mains paper with descriptive English and an interview; the clerk exam ends at mains.</p><p>Starting pay for a PO is roughly 1.6 times that of a clerk, and promotions to manager scale come faster.</p><p>The syllabus overlaps by about 80%, so a combined plan is efficient: prepare for PO-level depth, and the clerk paper becomes a speed test.</p><p>Decide on your target based on how soon you need a job and how comfortable you are with interviews.</p>', '/assets/demo/finance-calc.jpg', 'Lakshmi Krishnan', '2026-10-25', 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(10, 3, 'How to Build a 6-Month CAT Study Plan', 'how-to-build-a-6-month-cat-study-plan', 'A month-by-month plan that balances concepts, sectional practice and full-length mocks.', '<p>Six months is enough time for CAT if you split it into three clear phases: concepts, application and simulation.</p><p>In the first two months, cover every Quant topic and read one long article a day for VARC. Keep DILR practice light but regular: two sets a day.</p><p>From month three, move to timed sectional tests. Log every mistake by topic and type, and revise the log every Sunday.</p><p>The last two months are for full-length mocks: two a week, each followed by an analysis session that takes longer than the mock itself.</p>', '/assets/demo/desk-planner.jpg', 'Dr. Arun Mehta', '2026-10-16', 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(11, 3, 'NEET Biology: The Chapters That Decide Your Rank', 'neet-biology-the-chapters-that-decide-your-rank', 'Ten NCERT chapters account for nearly half of the biology questions. Start there.', '<p>Biology is 360 of the 720 marks in NEET, and the questions stay very close to NCERT text.</p><p>Human Physiology, Genetics, Ecology, Plant Physiology and Cell Biology together contribute the largest share every year.</p><p>Read each chapter line by line, then turn diagrams into flashcards. Revisit them every ten days.</p><p>Practise assertion–reason questions separately; they reward precise reading more than memory.</p>', '/assets/demo/medical-brain.jpg', 'Dr. Ishita Pillai', '2026-10-07', 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(12, 3, 'GATE: Subject-wise Weightage and Strategy', 'gate-subject-wise-weightage-and-strategy', 'Which subjects carry the most marks, and how to order your preparation around them.', '<p>General Aptitude and Engineering Mathematics together carry around 28 marks in most papers — the highest return for the time spent.</p><p>For core subjects, start with those that support others: for CS, Discrete Mathematics before Algorithms; for ME, Strength of Materials before Machine Design.</p><p>Solve previous-year questions topic-wise as soon as you finish a topic, not at the end.</p><p>Keep the last eight weeks for full-length tests and short revision notes.</p>', '/assets/demo/coding-1.jpg', 'Prof. Suresh Iyer', '2026-09-28', 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(13, 4, 'How to Build a 6-Month CAT Study Plan', 'how-to-build-a-6-month-cat-study-plan', 'A month-by-month plan that balances concepts, sectional practice and full-length mocks.', '<p>Six months is enough time for CAT if you split it into three clear phases: concepts, application and simulation.</p><p>In the first two months, cover every Quant topic and read one long article a day for VARC. Keep DILR practice light but regular: two sets a day.</p><p>From month three, move to timed sectional tests. Log every mistake by topic and type, and revise the log every Sunday.</p><p>The last two months are for full-length mocks: two a week, each followed by an analysis session that takes longer than the mock itself.</p>', '/assets/demo/desk-planner.jpg', 'Dr. Arun Mehta', '2026-10-25', 1, '2026-10-28 21:09:20', '2026-10-28 21:09:20'),
