INSERT INTO `email_templates` (`id`, `template_key`, `template_name`, `template_category`, `subject`, `html_content`, `text_content`, `description`, `variables`, `is_active`, `is_system_template`, `created_at`, `updated_at`) VALUES
(1, 'admin_credentials', 'Admin login credentials', 'account', 'Your EduSphere CenterHub login for {{center_name}}', '<p>Hello {{admin_name}},</p><p>Your admin account for <strong>{{center_name}}</strong> is ready.</p><p>Username: <strong>{{username}}</strong><br>Temporary password: <strong>{{password}}</strong></p><p><a href=\"{{login_url}}\">Sign in</a> and change your password after the first login.</p><p>— EduSphere Academy</p>', 'Hello {{admin_name}}, your admin account for {{center_name}} is ready. Username: {{username}} Temporary password: {{password}} Sign in: {{login_url}}', 'Sent when a centre admin account is created', '[\"admin_name\",\"center_name\",\"username\",\"password\",\"login_url\"]', 1, 1, '2026-10-28 21:09:16', '2026-10-28 21:09:16'),
(2, 'password_reset', 'Password reset', 'account', 'Reset your EduSphere CenterHub password', '<p>Hello {{user_name}},</p><p>We received a request to reset the password for your {{user_type}} account.</p><p><a href=\"{{reset_url}}\">Choose a new password</a>. The link expires in one hour.</p><p>If you did not ask for this, you can ignore this email.</p><p>— EduSphere Academy</p>', 'Hello {{user_name}}, reset your {{user_type}} password here: {{reset_url}} (expires in one hour).', 'Sent from the Forgot password page', '[\"user_name\",\"user_type\",\"reset_url\"]', 1, 1, '2026-10-28 21:09:16', '2026-10-28 21:09:16');
