INSERT INTO `faqs` (`id`, `center_id`, `question`, `answer`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'Which courses are available at this centre?', 'We offer classroom, online live and hybrid programs for CAT/MBA, Bank exams, GATE, GMAT, ICET, JEE, NEET, CLAT and IPM. Course availability differs slightly by centre.', 0, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(2, 1, 'Can I attend a demo class before enrolling?', 'Yes. Every course has a free demo class. Book one from the course page or call the centre and we will schedule it this week.', 1, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(3, 1, 'Do you offer scholarships?', 'Yes. Our free scholarship test runs every Sunday at 10:00 AM. Depending on your score you can get up to 100% off the course fee.', 2, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(4, 1, 'Can I pay the fee in instalments?', 'Most courses allow up to three instalments after a registration fee. The exact schedule is shown on the course page and on your fee receipt.', 3, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(5, 1, 'Is study material included in the fee?', 'Yes. Printed booklets (for classroom courses), the online test portal and the mobile app are all included.', 4, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(6, 1, 'What happens if I miss a class?', 'Recordings of every class are available in the student portal within 24 hours, and you can attend the same topic in a parallel batch.', 5, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(7, 2, 'Which courses are available at this centre?', 'We offer classroom, online live and hybrid programs for CAT/MBA, Bank exams, GATE, GMAT, ICET, JEE, NEET, CLAT and IPM. Course availability differs slightly by centre.', 0, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(8, 2, 'Can I attend a demo class before enrolling?', 'Yes. Every course has a free demo class. Book one from the course page or call the centre and we will schedule it this week.', 1, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(9, 2, 'Do you offer scholarships?', 'Yes. Our free scholarship test runs every Sunday at 10:00 AM. Depending on your score you can get up to 100% off the course fee.', 2, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(10, 2, 'Can I pay the fee in instalments?', 'Most courses allow up to three instalments after a registration fee. The exact schedule is shown on the course page and on your fee receipt.', 3, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(11, 2, 'Is study material included in the fee?', 'Yes. Printed booklets (for classroom courses), the online test portal and the mobile app are all included.', 4, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(12, 2, 'What happens if I miss a class?', 'Recordings of every class are available in the student portal within 24 hours, and you can attend the same topic in a parallel batch.', 5, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(13, 3, 'Which courses are available at this centre?', 'We offer classroom, online live and hybrid programs for CAT/MBA, Bank exams, GATE, GMAT, ICET, JEE, NEET, CLAT and IPM. Course availability differs slightly by centre.', 0, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(14, 3, 'Can I attend a demo class before enrolling?', 'Yes. Every course has a free demo class. Book one from the course page or call the centre and we will schedule it this week.', 1, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(15, 3, 'Do you offer scholarships?', 'Yes. Our free scholarship test runs every Sunday at 10:00 AM. Depending on your score you can get up to 100% off the course fee.', 2, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(16, 3, 'Can I pay the fee in instalments?', 'Most courses allow up to three instalments after a registration fee. The exact schedule is shown on the course page and on your fee receipt.', 3, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
