INSERT INTO `leadership` (`id`, `center_id`, `name`, `role`, `image_url`, `message_title`, `message_content`, `bio`, `created_at`, `updated_at`, `display_order`, `is_active`) VALUES
(1, 1, 'Ananya Iyer', 'Centre Director — EduSphere Chennai Central', '/assets/demo/woman-2.jpg', 'A message from the Centre Director', 'At EduSphere Chennai Central we believe every student can reach their goal with the right plan and steady practice. Our faculty track each student individually, and our doors are always open for students and parents. We look forward to being part of your journey.', 'Ananya Iyer has led academic programs for over twelve years and has mentored more than 5,000 students for competitive exams.', '2026-10-28 21:09:17', '2026-10-28 21:09:17', 0, 1),
(2, 2, 'Kavya Kulkarni', 'Centre Director — EduSphere Bengaluru Koramangala', '/assets/demo/woman-3.jpg', 'A message from the Centre Director', 'At EduSphere Bengaluru Koramangala we believe every student can reach their goal with the right plan and steady practice. Our faculty track each student individually, and our doors are always open for students and parents. We look forward to being part of your journey.', 'Kavya Kulkarni has led academic programs for over twelve years and has mentored more than 5,000 students for competitive exams.', '2026-10-28 21:09:18', '2026-10-28 21:09:18', 0, 1),
(3, 3, 'Pooja Patel', 'Centre Director — EduSphere Hyderabad Ameerpet', '/assets/demo/woman-4.jpg', 'A message from the Centre Director', 'At EduSphere Hyderabad Ameerpet we believe every student can reach their goal with the right plan and steady practice. Our faculty track each student individually, and our doors are always open for students and parents. We look forward to being part of your journey.', 'Pooja Patel has led academic programs for over twelve years and has mentored more than 5,000 students for competitive exams.', '2026-10-28 21:09:19', '2026-10-28 21:09:19', 0, 1),
(4, 4, 'Tanvi Chatterjee', 'Centre Director — EduSphere Pune Deccan', '/assets/demo/woman-5.jpg', 'A message from the Centre Director', 'At EduSphere Pune Deccan we believe every student can reach their goal with the right plan and steady practice. Our faculty track each student individually, and our doors are always open for students and parents. We look forward to being part of your journey.', 'Tanvi Chatterjee has led academic programs for over twelve years and has mentored more than 5,000 students for competitive exams.', '2026-10-28 21:09:20', '2026-10-28 21:09:20', 0, 1),
(5, 5, 'Lakshmi Iyer', 'Centre Director — EduSphere Delhi Laxmi Nagar', '/assets/demo/woman-2.jpg', 'A message from the Centre Director', 'At EduSphere Delhi Laxmi Nagar we believe every student can reach their goal with the right plan and steady practice. Our faculty track each student individually, and our doors are always open for students and parents. We look forward to being part of your journey.', 'Lakshmi Iyer has led academic programs for over twelve years and has mentored more than 5,000 students for competitive exams.', '2026-10-28 21:09:21', '2026-10-28 21:09:21', 0, 1),
(6, 6, 'Neha Kulkarni', 'Centre Director — EduSphere Kolkata Salt Lake', '/assets/demo/woman-1.jpg', 'A message from the Centre Director', 'At EduSphere Kolkata Salt Lake we believe every student can reach their goal with the right plan and steady practice. Our faculty track each student individually, and our doors are always open for students and parents. We look forward to being part of your journey.', 'Neha Kulkarni has led academic programs for over twelve years and has mentored more than 5,000 students for competitive exams.', '2026-10-28 21:09:22', '2026-10-28 21:09:22', 0, 1);
