INSERT INTO `student_stories` (`id`, `center_id`, `student_name`, `student_image_url`, `course_name`, `batch_year`, `achievement_title`, `story_content`, `testimonial_quote`, `video_url`, `display_order`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'Sneha Reddy', '/assets/demo/woman-3.jpg', 'GATE', '2026', 'From tier-3 college to GATE AIR 46', 'Sneha studied four hours a day for ten months, using the subject-wise tests to decide what to revise each week. She now works at a Maharatna PSU and mentors our current GATE batch on weekends.', 'Consistency beat intensity for me.', NULL, 0, 1, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(2, 1, 'Priya Das', '/assets/demo/woman-6.jpg', 'CLAT', '2026', 'CLAT AIR 18, NLSIU Bengaluru', 'Priya followed the daily legal-news analysis and the reading-speed programme from Class 11. She now studies at NLSIU and returns every year to talk to new students.', 'Reading the news every day became a habit, not a chore.', NULL, 1, 0, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(3, 1, 'Vikram Singh', '/assets/demo/man-2.jpg', 'Bank Exams', '2026', 'Second attempt, SBI PO selection', 'After missing the cut-off in his first attempt, Vikram joined the combo course. Daily speed-maths drills and mock interviews with retired bankers helped him clear prelims, mains and the final interview.', 'Interview practice turned my nerves into preparation.', NULL, 2, 0, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(4, 2, 'Vikram Singh', '/assets/demo/man-2.jpg', 'Bank Exams', '2026', 'Second attempt, SBI PO selection', 'After missing the cut-off in his first attempt, Vikram joined the combo course. Daily speed-maths drills and mock interviews with retired bankers helped him clear prelims, mains and the final interview.', 'Interview practice turned my nerves into preparation.', NULL, 0, 1, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(5, 2, 'Priya Das', '/assets/demo/woman-6.jpg', 'CLAT', '2026', 'CLAT AIR 18, NLSIU Bengaluru', 'Priya followed the daily legal-news analysis and the reading-speed programme from Class 11. She now studies at NLSIU and returns every year to talk to new students.', 'Reading the news every day became a habit, not a chore.', NULL, 1, 0, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(6, 2, 'Ananya Iyer', '/assets/demo/woman-1.jpg', 'CAT / MBA', '2025', '99.92 percentile and an IIM Ahmedabad admit', 'Ananya joined the weekend classroom batch while working at a bank. She attempted 62 full-length mocks and kept an error log for each one. Her mentor helped her move from 85 to 99.92 percentile in eight months by fixing two weak areas: geometry and para-jumbles.', 'Every mock was a lesson, not just a score.', NULL, 2, 0, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
(7, 3, 'Priya Das', '/assets/demo/woman-6.jpg', 'CLAT', '2026', 'CLAT AIR 18, NLSIU Bengaluru', 'Priya followed the daily legal-news analysis and the reading-speed programme from Class 11. She now studies at NLSIU and returns every year to talk to new students.', 'Reading the news every day became a habit, not a chore.', NULL, 0, 1, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(8, 3, 'Arjun Kulkarni', '/assets/demo/man-4.jpg', 'JEE/Engg', '2026', 'JEE Advanced AIR 112 after the 2-year program', 'Arjun joined in Class 11 and took 48 part tests over two years. Parent–teacher meetings every term kept the family involved, and he chose Computer Science at IIT Bombay.', 'The part tests made the real exam feel familiar.', NULL, 1, 0, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(9, 3, 'Ananya Iyer', '/assets/demo/woman-1.jpg', 'CAT / MBA', '2025', '99.92 percentile and an IIM Ahmedabad admit', 'Ananya joined the weekend classroom batch while working at a bank. She attempted 62 full-length mocks and kept an error log for each one. Her mentor helped her move from 85 to 99.92 percentile in eight months by fixing two weak areas: geometry and para-jumbles.', 'Every mock was a lesson, not just a score.', NULL, 2, 0, 1, '2026-10-28 21:09:19', '2026-10-28 21:09:19'),
(10, 4, 'Arjun Kulkarni', '/assets/demo/man-4.jpg', 'JEE/Engg', '2026', 'JEE Advanced AIR 112 after the 2-year program', 'Arjun joined in Class 11 and took 48 part tests over two years. Parent–teacher meetings every term kept the family involved, and he chose Computer Science at IIT Bombay.', 'The part tests made the real exam feel familiar.', NULL, 0, 1, 1, '2026-10-28 21:09:20', '2026-10-28 21:09:20'),
