INSERT INTO `text_testimonials` (`id`, `center_id`, `quote`, `author_name`, `author_role`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 1, 'The 1:1 GMAT sessions were worth every rupee. My verbal score went up by eight points in six weeks.', 'Karthik Raman', 'GMAT Focus 755', 0, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(2, 1, 'Reading speed was my weakest point. The CLAT reading programme took me from 180 to 300 words per minute in three months.', 'Priya Das', 'CLAT AIR 18, NLSIU Bengaluru', 1, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(3, 1, 'My son was nervous about Class 11 physics. The mentors met us every term and his confidence is completely different now.', 'Mrs. Sunita Kulkarni', 'Parent, JEE 2-Year Program', 2, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(4, 1, 'I failed the IBPS PO mains once before joining. The interview panel practice with retired bank managers made the difference.', 'Vikram Singh', 'Probationary Officer, SBI', 3, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(5, 1, 'The weekly sectional tests changed how I approached CAT. By the final month I knew exactly where I lost marks and how to fix it.', 'Ananya Iyer', 'CAT 99.92 percentile, IIM Ahmedabad', 4, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(6, 1, 'Faculty here actually answer your doubts the same day. That alone kept me going through a full-time job and GATE preparation.', 'Sneha Reddy', 'GATE CS AIR 46', 5, 1, '2026-10-28 21:09:17', '2026-10-28 21:09:17'),
(7, 2, 'My son was nervous about Class 11 physics. The mentors met us every term and his confidence is completely different now.', 'Mrs. Sunita Kulkarni', 'Parent, JEE 2-Year Program', 0, 1, '2026-10-28 21:09:18', '2026-10-28 21:09:18'),
