INSERT INTO `website_leadership` (`id`, `name`, `role`, `image_url`, `message_title`, `message_content`, `bio`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Dr. Rajesh Krishnan', 'Founder & Managing Director', '/assets/demo/man-senior-1.jpg', 'Why we started EduSphere', 'We started EduSphere with one classroom and a simple promise: every student deserves a teacher who knows their name and a plan that fits their goal. Twenty years later, that promise still guides every centre we open.', 'IIT Madras and IIM Calcutta alumnus. Has taught quantitative aptitude for over 25 years.', 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(2, 'Anita Sharma', 'Co-founder & Director, Academics', '/assets/demo/woman-2.jpg', 'On teaching that works', 'Good teaching is not about covering the syllabus faster. It is about knowing what each student finds hard and giving them the right practice at the right time.', 'Former professor of English literature; leads curriculum design across all exam tracks.', 1, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(3, 'Vivek Menon', 'Director, Operations', '/assets/demo/man-suit.jpg', 'Building centres students love', 'Every centre should feel like a place you want to come back to — quiet study spaces, helpful staff and faculty who stay after class.', 'Fifteen years in education operations; oversees all EduSphere centres.', 2, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23');
