(1, 'Free scholarship test this Sunday', 'Win up to 100% off on course fees. Register online or walk in by 9:30 AM.', NULL, 1, 0, 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(2, 'New CAT 2027 weekend batch starts next month', 'Limited to 40 seats. Early-bird discount available until the 15th.', NULL, 1, 0, 1, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(3, 'GATE results: 38 students in the top 1000', 'Congratulations to our GATE students for an outstanding result this year.', NULL, 0, 0, 2, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(4, 'Parent–teacher meeting for JEE and NEET batches', 'Meet the faculty and review your child’s progress on Saturday from 10 AM to 1 PM.', NULL, 0, 0, 3, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(5, 'Library timings extended during exam season', 'The self-study hall is now open from 7 AM to 10 PM on all days.', NULL, 0, 0, 4, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(6, 'Admissions open for the new academic year', 'Visit the centre or apply online.', NULL, 1, 1, 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
