INSERT INTO `website_senior_faculty` (`id`, `name`, `role`, `description`, `image_url`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Dr. Arun Mehta', 'Senior Quant Faculty', 'Leads CAT / MBA academics across all centres. 13 years of teaching experience.', '/assets/demo/man-senior-1.jpg', 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(2, 'Vikram Rao', 'Reasoning Faculty', 'Leads Bank Exams academics across all centres. 10 years of teaching experience.', '/assets/demo/man-2.jpg', 1, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(3, 'Prof. Suresh Iyer', 'Computer Science Faculty', 'Leads GATE academics across all centres. 17 years of teaching experience.', '/assets/demo/man-senior-2.jpg', 2, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(4, 'Karthik Raman', 'GMAT Verbal Mentor', 'Leads GMAT academics across all centres. 17 years of teaching experience.', '/assets/demo/man-3.jpg', 3, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(5, 'Sameer Patel', 'Analytical Ability Faculty', 'Leads ICET academics across all centres. 19 years of teaching experience.', '/assets/demo/man-4.jpg', 4, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(6, 'Dr. Rakesh Verma', 'Physics Faculty', 'Leads JEE/Engg academics across all centres. 10 years of teaching experience.', '/assets/demo/man-suit.jpg', 5, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23');
INSERT INTO `website_student_stories` (`id`, `student_name`, `student_image_url`, `course_name`, `batch_year`, `achievement_title`, `story_content`, `testimonial_quote`, `video_url`, `display_order`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Ananya Iyer', '/assets/demo/woman-1.jpg', 'CAT / MBA', '2025', '99.92 percentile and an IIM Ahmedabad admit', 'Ananya joined the weekend classroom batch while working at a bank. She attempted 62 full-length mocks and kept an error log for each one. Her mentor helped her move from 85 to 99.92 percentile in eight months by fixing two weak areas: geometry and para-jumbles.', 'Every mock was a lesson, not just a score.', NULL, 0, 1, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(2, 'Sneha Reddy', '/assets/demo/woman-3.jpg', 'GATE', '2026', 'From tier-3 college to GATE AIR 46', 'Sneha studied four hours a day for ten months, using the subject-wise tests to decide what to revise each week. She now works at a Maharatna PSU and mentors our current GATE batch on weekends.', 'Consistency beat intensity for me.', NULL, 1, 1, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(3, 'Arjun Kulkarni', '/assets/demo/man-4.jpg', 'JEE/Engg', '2026', 'JEE Advanced AIR 112 after the 2-year program', 'Arjun joined in Class 11 and took 48 part tests over two years. Parent–teacher meetings every term kept the family involved, and he chose Computer Science at IIT Bombay.', 'The part tests made the real exam feel familiar.', NULL, 2, 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(4, 'Vikram Singh', '/assets/demo/man-2.jpg', 'Bank Exams', '2026', 'Second attempt, SBI PO selection', 'After missing the cut-off in his first attempt, Vikram joined the combo course. Daily speed-maths drills and mock interviews with retired bankers helped him clear prelims, mains and the final interview.', 'Interview practice turned my nerves into preparation.', NULL, 3, 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(5, 'Priya Das', '/assets/demo/woman-6.jpg', 'CLAT', '2026', 'CLAT AIR 18, NLSIU Bengaluru', 'Priya followed the daily legal-news analysis and the reading-speed programme from Class 11. She now studies at NLSIU and returns every year to talk to new students.', 'Reading the news every day became a habit, not a chore.', NULL, 4, 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23');
INSERT INTO `website_text_testimonials` (`id`, `quote`, `author_name`, `author_role`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'The weekly sectional tests changed how I approached CAT. By the final month I knew exactly where I lost marks and how to fix it.', 'Ananya Iyer', 'CAT 99.92 percentile, IIM Ahmedabad', 0, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(2, 'Faculty here actually answer your doubts the same day. That alone kept me going through a full-time job and GATE preparation.', 'Sneha Reddy', 'GATE CS AIR 46', 1, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(3, 'I failed the IBPS PO mains once before joining. The interview panel practice with retired bank managers made the difference.', 'Vikram Singh', 'Probationary Officer, SBI', 2, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(4, 'My son was nervous about Class 11 physics. The mentors met us every term and his confidence is completely different now.', 'Mrs. Sunita Kulkarni', 'Parent, JEE 2-Year Program', 3, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(5, 'The NEET biology workbooks and the diagram drills are the reason I could finish the paper with time to revise.', 'Meera Joshi', 'NEET 695/720', 4, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(6, 'Reading speed was my weakest point. The CLAT reading programme took me from 180 to 300 words per minute in three months.', 'Priya Das', 'CLAT AIR 18, NLSIU Bengaluru', 5, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(7, 'Online live classes felt like a classroom — small groups, cameras on, and the teacher knew everyone by name.', 'Rahul Menon', 'CAT 99.81 percentile', 6, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23'),
(8, 'The 1:1 GMAT sessions were worth every rupee. My verbal score went up by eight points in six weeks.', 'Karthik Raman', 'GMAT Focus 755', 7, 1, '2026-10-28 21:09:23', '2026-10-28 21:09:23');
